import csv
import io


def parse_csv(raw_csv: str):
    previous_limit = csv.field_size_limit()
    try:
        csv.field_size_limit(max(previous_limit, len(raw_csv)))
        reader = csv.reader(io.StringIO(raw_csv, newline=""), delimiter=";", quotechar='"')
        records = list(reader)
    finally:
        csv.field_size_limit(previous_limit)

    if not records:
        return {"columns": [], "rows": []}

    columns = records[0]
    if columns:
        columns[0] = columns[0].removeprefix("\ufeff")

    rows = records[1:]
    width = max([len(columns)] + [len(row) for row in rows])
    used = set(columns)

    while len(columns) < width:
        base = "column_" + str(len(columns) + 1)
        name = base
        suffix = 2
        while name in used:
            name = base + "_" + str(suffix)
            suffix += 1
        columns.append(name)
        used.add(name)

    for row in rows:
        row.extend([""] * (width - len(row)))

    return {"columns": columns, "rows": rows}
